def q(text, *refs):
    """Цитата: «текст»（ссылки）"""
    return f"<blockquote><p>「{text}」（{'、'.join(refs)}）</p></blockquote>"


def src(*refs):
    return f"<p>（{'、'.join(refs)}）</p>"


def ii(ep, refs):
    """Несколько мест одного послания: ii('R', [(1, 2), (8, 3), (9, '2-3')]) -> 『…』1:2、8:3、9:2-3"""
    path, title = EP[ep]
    parts = [f'<a href="https://bibleox.com/ja/ja/w/{path}#HH-{ch}">{ch}:{sec}</a>' if sec else f'<a href="https://bibleox.com/ja/ja/w/{path}#HH-{ch}">{ch}章</a>' for ch, sec in refs]
    return f"『{title}』" + '、'.join(parts)


def ep0(ep):
    """Ссылка на приветствие послания (глава 0)"""
    path, title = EP[ep]
    return f'<a href="https://bibleox.com/ja/ja/w/{path}#HH-0">『{title}』序</a>'


